#nullable enable // autogenerated

using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Pickups;
using MVZ2.Vanilla.Properties;
using PVZEngine;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaEntityBehaviourNames.gemBall)]
    public class GemBallBehaviour : GoldenBall
    {
        public GemBallBehaviour(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.POST_PROJECTILE_HIT, PostHitEntityCallback, VanillaCallbackPriorities.LATE);
        }
        private void PostHitEntityCallback(VanillaLevelCallbacks.PostProjectileHitParams param, CallbackResult result)
        {
            var hitResult = param.hit;
            var projectile = hitResult.Projectile;
            if (!projectile.Definition.HasBehaviour(this))
                return;
            NamespaceID? gemID = projectile.GetProperty<NamespaceID>(PROP_GEM_ID);
            if (projectile.RNG.Next(100) < projectile.GetProperty<float>(PROP_GEM_CHANCE) && gemID != null)
            {
                projectile.Produce(gemID);
            }
        }
        public static readonly VanillaEntityPropertyMeta<float> PROP_GEM_CHANCE = new VanillaEntityPropertyMeta<float>("gem_chance");
        public static readonly VanillaEntityPropertyMeta<NamespaceID> PROP_GEM_ID = new VanillaEntityPropertyMeta<NamespaceID>("gem_id");
    }
}
